variante_1.css:
:root {
  --sl-primary: #007bff;
  --sl-accent: #6c757d;
  --sl-text-main: #212529;
  --sl-bg-body: #f8f9fa;
  --sl-primary-rgb: 0, 123, 255;
  --sl-header-bg: #ffffff;
  --sl-footer-bg: #343a40;
  --sl-footer-text: #ffffff;
  --sl-card-bg: #ffffff;
  --sl-border: #dee2e6;
}

@media (prefers-color-scheme: dark) {
  :root {
    --sl-primary: #66b3ff;
    --sl-accent: #adb5bd;
    --sl-text-main: #e9ecef;
    --sl-bg-body: #212529;
    --sl-primary-rgb: 102, 179, 255;
    --sl-header-bg: #2c3034;
    --sl-footer-bg: #1a1d20;
    --sl-footer-text: #e9ecef;
    --sl-card-bg: #2c3034;
    --sl-border: #495057;
  }
}

body {
  background-color: var(--sl-bg-body);
  color: var(--sl-text-main);
}

.text-sl-primary { color: var(--sl-primary) !important; }
.text-sl-accent { color: var(--sl-accent) !important; }
.text-sl-text-main { color: var(--sl-text-main) !important; }
.bg-sl-body { background-color: var(--sl-bg-body) !important; }
.bg-sl-card-bg { background-color: var(--sl-card-bg) !important; }
.border-sl-border { border-color: var(--sl-border) !important; }

.btn-outline-sl-primary {
  --bs-btn-color: var(--sl-primary);
  --bs-btn-border-color: var(--sl-primary);
  --bs-btn-hover-color: #fff;
  --bs-btn-hover-bg: var(--sl-primary);
  --bs-btn-hover-border-color: var(--sl-primary);
  --bs-btn-focus-shadow-rgb: var(--sl-primary-rgb);
  --bs-btn-active-color: #fff;
  --bs-btn-active-bg: var(--sl-primary);
  --bs-btn-active-border-color: var(--sl-primary);
  --bs-btn-active-shadow: inset 0 3px 5px rgba(0, 0, 0, 0.125);
  --bs-btn-disabled-color: var(--sl-primary);
  --bs-btn-disabled-border-color: var(--sl-primary);
}

.text-bg-sl-primary {
  color: var(--bs-white) !important;
  background-color: var(--sl-primary) !important;
}

.blog-post-content h1,
.blog-post-content h2,
.blog-post-content h3,
.blog-post-content h4,
.blog-post-content h5,
.blog-post-content h6 {
  color: var(--sl-text-main);
  margin-top: 2rem;
  margin-bottom: 1rem;
}

.blog-post-content p {
  margin-bottom: 1rem;
  line-height: 1.7;
}

.blog-post-content ul,
.blog-post-content ol {
  padding-left: 1.5rem;
  margin-bottom: 1rem;
}

.blog-post-content ul li,
.blog-post-content ol li {
  margin-bottom: 0.5rem;
}

.blog-post-content a {
  color: var(--sl-primary);
  text-decoration: underline;
}

.blog-post-content a:hover {
  color: var(--sl-primary);
  text-decoration: none;
}

.blog-post-content img {
  max-width: 100%;
  height: auto;
  border-radius: .25rem;
  margin-top: 1rem;
  margin-bottom: 1rem;
}

.blog-post-content pre {
  background-color: var(--sl-card-bg);
  border: 1px solid var(--sl-border);
  padding: 1rem;
  border-radius: .25rem;
  overflow-x: auto;
}

.blog-post-content code {
  font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, Courier, monospace;
  font-size: 87.5%;
  color: var(--sl-primary);
  word-wrap: break-word;
}

.blog-post-content pre code {
  color: inherit;
}

.breadcrumb-item + .breadcrumb-item::before {
  content: var(--bs-breadcrumb-divider, "/") !important;
  color: var(--sl-accent);
}

.breadcrumb-item a {
  color: var(--sl-primary);
}

.breadcrumb-item.active {
  color: var(--sl-accent);
}

