document.addEventListener('DOMContentLoaded', function() {
  // Read time calculation
  const articleContent = document.querySelector('.blog-post-content');
  if (articleContent) {
    const text = articleContent.textContent || articleContent.innerText;
    const wordsPerMinute = 200; // Average reading speed
    const wordCount = text.split(/\s+/).filter(word => word.length > 0).length;
    const readTime = Math.ceil(wordCount / wordsPerMinute);
    const readTimeDisplay = document.querySelector('#read-time-display-v3 .read-time-value');
    if (readTimeDisplay) {
      readTimeDisplay.textContent = readTime;
    }
  }

  // Table of Contents (TOC) generation and sticky behavior
  const tocContainer = document.getElementById('table-of-contents');
  const headings = articleContent ? articleContent.querySelectorAll('h2, h3') : [];
  const headingOffsets = [];

  if (tocContainer && headings.length > 0) {
    const tocList = document.createElement('ul');
    tocList.classList.add('list-unstyled', 'mb-0');

    headings.forEach((heading, index) => {
      const id = heading.id || `toc-section-${index}`;
      heading.id = id; // Ensure all headings have an ID
      const text = heading.textContent;
      const level = heading.tagName.toLowerCase(); // h2 or h3

      const listItem = document.createElement('li');
      const link = document.createElement('a');
      link.href = `#${id}`;
      link.textContent = text;
      link.classList.add('nav-link', level); // Add level class for styling
      link.addEventListener('click', function(e) {
        e.preventDefault();
        document.getElementById(id).scrollIntoView({ behavior: 'smooth', block: 'start' });
        // Update URL hash without page reload
        history.pushState(null, '', `#${id}`);
      });
      listItem.appendChild(link);
      tocList.appendChild(listItem);

      headingOffsets.push({ id: id, offset: heading.offsetTop });
    });
    tocContainer.appendChild(tocList);

    // Highlight active TOC item on scroll
    const updateActiveTocLink = () => {
      let currentActive = null;
      const scrollPosition = window.scrollY + 100; // Add offset for better UX

      for (let i = headingOffsets.length - 1; i >= 0; i--) {
        if (scrollPosition >= headingOffsets[i].offset) {
          currentActive = headingOffsets[i].id;
          break;
        }
      }

      document.querySelectorAll('#table-of-contents .nav-link').forEach(link => {
        link.classList.remove('active');
        if (link.getAttribute('href') === `#${currentActive}`) {
          link.classList.add('active');
        }
      });
    };

    window.addEventListener('scroll', updateActiveTocLink);
    updateActiveTocLink(); // Initial call
  }
});
